import java.util.Arrays;

public class TopWordsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("clear winner and runner-up", "[a, b]",
                    Arrays.toString(TopWords.topTwo(new String[]{"a", "b", "a", "c", "b", "a"})));
            check("full tie broken alphabetically", "[apple, pear]",
                    Arrays.toString(TopWords.topTwo(new String[]{"pear", "apple", "pear", "apple"})));
            check("three-way tie of singles", "[x, y]",
                    Arrays.toString(TopWords.topTwo(new String[]{"z", "y", "x"})));
            check("tie for second place", "[m, b]",
                    Arrays.toString(TopWords.topTwo(new String[]{"m", "m", "c", "b"})));
            check("one distinct word pads with null", "[hi, null]",
                    Arrays.toString(TopWords.topTwo(new String[]{"hi", "hi", "hi"})));
            check("empty input", "[null, null]",
                    Arrays.toString(TopWords.topTwo(new String[]{})));
            check("frequency beats alphabet", "[zebra, ant]",
                    Arrays.toString(TopWords.topTwo(new String[]{"ant", "zebra", "zebra"})));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

